class PurchaseInvoiceForm extends ConsumerStatefulWidget {
  final db.PurchaseInvoiceData? editInvoice;
  final bool isReturn;
  final Future<void> Function({
    required int? partyId,
    required String invoiceNumber,
    required String supplierInvoiceNumber,
    required DateTime date,
    required double total,
    required double discount,
    required double tax,
    required double netAmount,
    required double paidAmount,
    required String notes,
    required List<Map<String, dynamic>> items,
    required int? warehouseId,
    required int? costCenterId,
    required bool isDraft,
    required String paymentMethod,
    int? safeId,
    bool printAfterSave,
  }) onSave;

  const PurchaseInvoiceForm({
    super.key,
    this.editInvoice,
    this.isReturn = false,
    required this.onSave,
  });

  @override
  ConsumerState<PurchaseInvoiceForm> createState() => _PurchaseInvoiceFormState();
}

class _PurchaseInvoiceFormState extends ConsumerState<PurchaseInvoiceForm> {
  final _invoiceNumberController = TextEditingController();
  final _supplierInvoiceController = TextEditingController();
  final _notesController = TextEditingController();
  final _paidAmountController = TextEditingController();
  final _discountController = TextEditingController(text: '0');

  DateTime _selectedDate = DateTime.now();
  int? _selectedSupplierId;
  int? _selectedWarehouseId;
  int? _selectedCostCenterId;
  // Default supplier purchases to آجل (credit). A purchase from a supplier is
  // normally on account; defaulting to 'cash' silently forced paid=full and
  // auto-created a supplier payment voucher the operator never issued, which
  // zeroed the payable that should have stayed outstanding.
  String _paymentMethod = 'credit';
  int? _selectedSafeId;
  List<Map<String, dynamic>> _items = [];
  bool _isLoading = false;

  List<db.Category> _categories = [];
  List<db.Warehouse> _warehouses = [];
  List<db.CostCenter> _costCenters = [];

  @override
  void initState() {
    super.initState();
    _loadInitialData();
    if (widget.editInvoice != null) {
      _invoiceNumberController.text = widget.editInvoice!.invoiceNumber;
      _supplierInvoiceController.text = widget.editInvoice!.supplierInvoiceNumber ?? '';
      _notesController.text = widget.editInvoice!.notes ?? '';
      _paidAmountController.text = widget.editInvoice!.paid.toString();
      _discountController.text = widget.editInvoice!.discount.toString();
      _selectedDate = widget.editInvoice!.invoiceDate;
      _selectedSupplierId = widget.editInvoice!.supplierId;
      _selectedWarehouseId = widget.editInvoice!.warehouseId;
      _selectedCostCenterId = widget.editInvoice!.costCenterId;
      _paymentMethod = widget.editInvoice!.paymentMethod;
      _loadInvoiceItems();
    } else {
      // Leave the internal invoice number EMPTY so the backend's
      // DocumentSequences generator produces a short human-readable
      // number (e.g. "PINV-1", "PINV-2") at insert time. Pre-populating
      // with `PUR-<millisecondsSinceEpoch>` was the source of the
      // 13-digit ugly numbers shown on saved invoices.
      _invoiceNumberController.text = '';
      _paidAmountController.text = '0';
      _paymentMethod = 'credit';
    }
  }

  Future<void> _loadInitialData() async {
    final productRepo = ref.read(productRepositoryProvider);
    final branchRepo = ref.read(branchRepositoryProvider);
    final accountingRepo = ref.read(accountingRepositoryProvider);

    final cats = await productRepo.getCategories();
    // Spec 103 — الحصرُ يعيش في المستودع لا هنا: العرضُ لا يقرأ
    // `SharedPreferences` ولا يسأل عن وضع الجهاز. كان هذا الملفُّ بلا حصرٍ
    // إطلاقاً، فتُحفَظ الفاتورةُ بمخزنِ فرعٍ آخر فتغيب عن قائمة فرعها.
    final whs = await branchRepo.getScopedWarehouses();
    // `getActiveCostCenters` لا `getCostCenters`: الثانيةُ تُرجع المعطَّلَ كذلك،
    // فيظهر في القائمة مركزٌ أُوقف عمداً وتُرحَّل عليه فاتورة. والمسارات الثلاثة
    // العاملة تتّفق على الأولى — نافذةُ فاتورة المبيعات
    // (`sales_invoice_dialogs.dart:282`) وأمرُ البيع وأمرُ المشتريات — وهذا
    // الملفُّ كان وحدَه الشاذّ.
    //
    // ولا حصرَ فرعٍ على مراكز التكلفة: `CostCenters` بلا عمود `branchId`
    // أصلاً (accounting_tables.dart:107-119)، فالحصرُ غيرُ قابلٍ للتمثيل.
    final ccs = await accountingRepo.getActiveCostCenters();

    // ⊕ نطاقُ المستخدم **فوق** نطاقِ الجهاز — الاثنان معاً لا أحدُهما.
    // `getScopedWarehouses` تحصر بفرع **الجهاز** (وضعُ العميل، Spec 103)،
    // وهي لا ترى مستخدماً مخصَّصاً لفرعٍ على جهازٍ **مستقلّ**.
    // و`assignableWarehousesProvider` يحسم الأوضاعَ الأربعة من
    // `branchScopeProvider` ويُسقط المحذوفَ ناعماً والمعطَّل.
    //
    // فالتقاطعُ يُرضي الحدَّين ولا يوسّع أيَّهما: كلُّ ما يمنعه أحدُهما ممنوع.
    final assignableIds =
        (await ref.read(assignableWarehousesProvider(null).future))
            .map((w) => w.id)
            .toSet();
    final warehouses = List<db.Warehouse>.of(
      whs.where((w) => assignableIds.contains(w.id)),
    );
    final costCenters = List<db.CostCenter>.of(ccs);

    // وضعُ التحرير — ضمُّ قيمةِ الفاتورة نفسِها إن غابت عن القائمة المحصورة.
    //
    // القائمتان محصورتان عمداً للإنشاء: المخازنُ بفرع الجهاز (Spec 103)،
    // ومراكزُ التكلفة بالنشط وحدَه. لكنّ فاتورةً **قائمةً** قد تحمل مخزنَ فرعٍ
    // آخرَ (تُحرَّر على جهاز عميل) أو مركزَ تكلفةٍ أُوقف بعد إصدارها. حينئذٍ
    // تخرج قيمتُها من `items` فيُطلق `DropdownButtonFormField` توكيدَه في
    // debug ويرسم حقلاً فارغاً في release — ثم يُعاد الحفظُ بقيمةٍ أخرى صامتاً،
    // وهو بعينه الخطرُ الذي يحذّر منه `BranchRepository.getScopedWarehouses`.
    //
    // والضمُّ **بالمعرّف** لا برفع الحصر: صفٌّ واحدٌ هو صفُّ الفاتورة، فمسارُ
    // الإنشاء الجديد يبقى محصوراً كما هو.
    if (widget.editInvoice != null) {
      final whId = widget.editInvoice!.warehouseId;
      if (!warehouses.any((w) => w.id == whId)) {
        final missing = await branchRepo.getWarehouseById(whId);
        if (missing != null) warehouses.add(missing);
      }
      final ccId = widget.editInvoice!.costCenterId;
      if (ccId != null && !costCenters.any((c) => c.id == ccId)) {
        final missing = await accountingRepo.getCostCenterById(ccId);
        if (missing != null) costCenters.add(missing);
      }
    }

    if (mounted) {
      setState(() {
        _categories = cats;
        _warehouses = warehouses;
        _costCenters = costCenters;
        // فاتورةٌ جديدة: انتقِ المخزنَ الافتراضيَّ (وإلا أوّلَ متاح). بدون
        // هذا الانتقاء يصل `warehouseId: null` إلى المستودع فيحوّله `?? 1`
        // إلى المخزن رقم ١ — وقد لا يكون مخزنَ هذا الفرع ولا موجوداً أصلاً.
        // وبلا مخازنَ إطلاقاً يبقى `null` فيرفض الزرُّ بدل أن يخترع مخزناً.
        _selectedWarehouseId ??= warehouses
                .where((w) => w.isDefault)
                .firstOrNull
                ?.id ??
            warehouses.firstOrNull?.id;
        // ومركزُ التكلفةِ يتبع المخزنَ المنتقى — وهو ما يربطه بالفرع، إذ لا
        // عمودَ فرعٍ في `CostCenters`. وفي التحرير تحتفظ الفاتورةُ بمركزها.
        _selectedCostCenterId ??=
            _costCenterFor(_selectedWarehouseId, warehouses, costCenters);
      });
    }
  }

  /// مركزُ تكلفةِ [warehouseId] إن كان حاضراً في [costCenters] المحمَّلة.
  /// وشرطُ الحضورِ ليس تجميلاً: `DropdownButton` ينهار على قيمةٍ ليست في عناصره.
  int? _costCenterFor(
    int? warehouseId,
    List<db.Warehouse> warehouses,
    List<db.CostCenter> costCenters,
  ) {
    final costCenterId =
        warehouses.where((w) => w.id == warehouseId).firstOrNull?.costCenterId;
    if (costCenterId == null) return null;
    return costCenters.any((c) => c.id == costCenterId) ? costCenterId : null;
  }

  Future<void> _loadInvoiceItems() async {
    if (widget.editInvoice == null) return;
    final purchasesRepo = ref.read(purchasesRepositoryProvider);
    final itemsWithProduct = await purchasesRepo.getInvoiceItemsWithProduct(widget.editInvoice!.id);
    
    if (mounted) {
      setState(() {
        _items = itemsWithProduct.map((iwv) => {
          'productId': iwv.item.productId,
          'productName': iwv.product.name,
          'categoryId': iwv.product.categoryId,
          'quantity': iwv.item.quantity,
          'unitCost': iwv.item.unitCost,
          'taxRate': iwv.item.taxRate,
          'taxAmount': iwv.item.taxAmount,
          'taxEnabled': iwv.item.taxRate > 0,
          'lineTotal': iwv.item.total,
          'selectedUnitName': iwv.item.unitName,
          'trackExpiry': iwv.product.trackExpiry,
          'batchNumber': iwv.item.batchNumber,
          'expiryDate': iwv.item.expiryDate,
        }).toList();
      });
    }
  }

  double get _subtotal => _items.fold(0, (sum, item) => sum + (item['lineTotal'] as double));
  double get _taxTotal => _items.fold(0, (sum, item) => sum + (item['taxAmount'] as double));
  double get _discount => double.tryParse(_discountController.text) ?? 0;
  double get _netAmount => _subtotal + _taxTotal - _discount;

  String _getCategoryName(int? categoryId) {
    if (categoryId == null) return '-';
    return _categories.where((c) => c.id == categoryId).firstOrNull?.name ?? '-';
  }

  void _addItemToInvoice(db.Product product, {double? customCost}) {
    final existingIndex = _items.indexWhere((item) => item['productId'] == product.id);
    
    if (existingIndex != -1) {
      setState(() {
        final item = _items[existingIndex];
        final newQty = (item['quantity'] as double) + 1;
        final unitCost = (item['unitCost'] as double);
        final taxRate = (item['taxRate'] as double);
        
        final newLineTotal = FinancialUtils.calculateLineSubtotal(newQty, unitCost);
        final newTaxAmount = FinancialUtils.calculateTaxAmount(newLineTotal, taxRate);
        
        _items[existingIndex] = {
          ...item,
          'quantity': newQty,
          'lineTotal': newLineTotal,
          'taxAmount': newTaxAmount,
        };
      });
    } else {
      final cost = customCost ?? product.costPrice;
      final taxRate = product.taxRate;
      final subtotal = FinancialUtils.calculateLineSubtotal(1, cost);
      final taxAmount = FinancialUtils.calculateTaxAmount(subtotal, taxRate);
      
      setState(() {
        _items.add({
          'productId': product.id,
          'productName': product.name,
          'categoryId': product.categoryId,
          'quantity': 1.0,
          'unitCost': cost,
          'taxRate': taxRate,
          'taxAmount': taxAmount,
          'taxEnabled': taxRate > 0,
          'lineTotal': subtotal,
          'selectedUnitName': tr('قطعة'),
          'trackExpiry': product.trackExpiry,
        });
      });
    }
  }

  @override
  Widget build(BuildContext context) {
    return Padding(
      padding: const EdgeInsets.all(16.0),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          _buildFormHeader(),
          const SizedBox(height: 16),
          Expanded(
            child: Row(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Expanded(flex: 3, child: _buildItemsSection()),
                const SizedBox(width: 16),
                Expanded(flex: 1, child: _buildSummarySection()),
              ],
            ),
          ),
          const SizedBox(height: 16),
          _buildActionButtons(),
        ],
      ),
    );
  }

  Widget _buildFormHeader() {
    return Card(
      child: Padding(
        padding: const EdgeInsets.all(16.0),
        child: Column(
          children: [
            Row(
              children: [
                Expanded(
                  child: FutureBuilder<List<db.Party>>(
                    future: ref.read(productRepositoryProvider).getSuppliers(),
                    builder: (context, snapshot) {
                      final suppliers = snapshot.data ?? [];
                      return Autocomplete<db.Party>(
                        initialValue: TextEditingValue(
                          text: _selectedSupplierId != null 
                            ? (suppliers.where((s) => s.id == _selectedSupplierId).firstOrNull?.name ?? '')
                            : '',
                        ),
                        optionsBuilder: (textValue) {
                          if (textValue.text.isEmpty) return suppliers;
                          return suppliers.where((s) => s.name.contains(textValue.text));
                        },
                        displayStringForOption: (s) => s.name,
                        fieldViewBuilder: (context, controller, focusNode, onFieldSubmitted) {
                          return TextField(
                            controller: controller,
                            focusNode: focusNode,
                            decoration:  InputDecoration(
                              labelText: tr('المورد *'),
                              prefixIcon: const Icon(PhosphorIconsBold.truck),
                            ),
                          );
                        },
                        onSelected: (supplier) => setState(() => _selectedSupplierId = supplier.id),
                      );
                    },
                  ),
                ),
                const SizedBox(width: 16),
                Expanded(
                  child: TextFormField(
                    controller: _invoiceNumberController,
                    decoration:  InputDecoration(
                      labelText: tr('رقم الفاتورة'),
                      hintText: tr('يُنشأ تلقائياً'),
                      prefixIcon: const Icon(PhosphorIconsBold.hash),
                    ),
                  ),
                ),
                const SizedBox(width: 16),
                Expanded(
                  child: TextFormField(
                    controller: _supplierInvoiceController,
                    decoration:  InputDecoration(
                      labelText: tr('رقم الوثيقة (فاتورة المورد)'),
                      hintText: tr('رقم فاتورة المورد الوارد...'),
                      prefixIcon: const Icon(PhosphorIconsBold.fileText),
                    ),
                  ),
                ),
                const SizedBox(width: 16),
                Expanded(
                  child: InkWell(
                    onTap: () async {
                      final date = await showDatePicker(
                        context: context,
                        initialDate: _selectedDate,
                        firstDate: DateTime(2020),
                        lastDate: DateTime.now(),
                      );
                      if (date != null) setState(() => _selectedDate = date);
                    },
                    child: InputDecorator(
                      decoration:  InputDecoration(
                        labelText: tr('تاريخ الفاتورة'),
                        prefixIcon: const Icon(PhosphorIconsBold.calendar),
                      ),
                      child: Text('${_selectedDate.year}-${_selectedDate.month}-${_selectedDate.day}'),
                    ),
                  ),
                ),
              ],
            ),
            const SizedBox(height: 16),
            Row(
              children: [
                Expanded(
                  child: DropdownButtonFormField<int>(
                    initialValue: _selectedWarehouseId,
                    decoration:  InputDecoration(
                      labelText: tr('المخزن'),
                      prefixIcon: const Icon(PhosphorIconsBold.warehouse),
                    ),
                    items: _warehouses.map((w) => DropdownMenuItem(value: w.id, child: Text(trData(w.name)))).toList(),
                    onChanged: (val) => setState(() {
                      _selectedWarehouseId = val;
                      _selectedCostCenterId =
                          _costCenterFor(val, _warehouses, _costCenters);
                    }),
                  ),
                ),
                const SizedBox(width: 16),
                Expanded(
                  child: DropdownButtonFormField<int>(
                    initialValue: _selectedCostCenterId,
                    decoration:  InputDecoration(
                      labelText: tr('مركز التكلفة'),
                      prefixIcon: const Icon(PhosphorIconsBold.chartPieSlice),
                    ),
                    items: _costCenters.map((cc) => DropdownMenuItem(value: cc.id, child: Text(trData(cc.name)))).toList(),
                    onChanged: (val) => setState(() => _selectedCostCenterId = val),
                  ),
                ),
              ],
            ),
          ],
        ),
      ),
    );
  }

  Widget _buildItemsSection() {
    return Column(
      children: [
        Row(
          children: [
             Text(tr('الأصناف'), style: const TextStyle(fontSize: 18, fontWeight: FontWeight.bold)),
            const Spacer(),
            ElevatedButton.icon(
              onPressed: () async {
                final result = await AddProductDialog.show(context, simplified: true);
                if (result != null) {
                  // ISS-06: Acceptable — one-shot read in button callback, provider exists
                  // (productByIdProvider) for future refactor to reactive pattern.
                  final db_ = ref.read(databaseProvider);
                  final product = await db_.getProductById(result.productId);
                  // Null safety check for product properties in case generator hasn't finished
                  if (product != null) _addItemToInvoice(product, customCost: result.costPrice);
                }
              },
              icon: const Icon(PhosphorIconsBold.plus, size: 16),
              label:  Text(tr('صنف جديد')),
            ),
            const SizedBox(width: 8),
            // Product Search / Selector
            SizedBox(
              width: 250,
              child: FutureBuilder<List<db.Product>>(
                future: ref.read(productRepositoryProvider).getAllProducts(),
                builder: (context, snapshot) {
                  final products = snapshot.data ?? [];
                  TextEditingController? acController;
                  return Autocomplete<db.Product>(
                    optionsBuilder: (textValue) {
                      if (textValue.text.isEmpty) return [];
                      return products.where((p) => 
                        p.name.toLowerCase().contains(textValue.text.toLowerCase()) ||
                        (p.barcode != null && p.barcode!.contains(textValue.text)) ||
                        p.code.toLowerCase().contains(textValue.text.toLowerCase())
                      );
                    },
                    displayStringForOption: (p) => p.name,
                    fieldViewBuilder: (context, controller, focusNode, onFieldSubmitted) {
                      acController = controller;
                      return TextField(
                        controller: controller,
                        focusNode: focusNode,
                        decoration:  InputDecoration(
                          hintText: tr('ابحث عن صنف...'),
                          isDense: true,
                          prefixIcon: const Icon(PhosphorIconsBold.magnifyingGlass, size: 18),
                        ),
                      );
                    },
                    onSelected: (p) {
                      _addItemToInvoice(p);
                      WidgetsBinding.instance.addPostFrameCallback((_) {
                        acController?.clear();
                      });
                    },
                  );
                },
              ),
            ),
          ],
        ),
        const SizedBox(height: 8),
        Expanded(
          child: PurchaseInvoiceItemsTable(
            items: _items,
            getCategoryName: _getCategoryName,
            onItemChanged: (index, updatedItem) {
              setState(() => _items[index] = updatedItem);
            },
            onItemRemoved: (index) {
              setState(() => _items.removeAt(index));
            },
          ),
        ),
      ],
    );
  }

  Widget _buildSummarySection() {
    return Card(
      color: AppColors.surface,
      child: Padding(
        padding: const EdgeInsets.all(16.0),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
             Text(tr('الخلاصة المادية'), style: const TextStyle(fontSize: 16, fontWeight: FontWeight.bold)),
            const Divider(),
            _buildSummaryRow(tr('الإجمالي قبل الضريبة'), _subtotal),
            _buildSummaryRow(tr('إجمالي الضريبة'), _taxTotal),
            const SizedBox(height: 8),
            TextFormField(
              controller: _discountController,
              decoration:  InputDecoration(labelText: tr('الخصم'), isDense: true),
              keyboardType: TextInputType.number,
              onChanged: (_) => setState(() {}),
            ),
            const Divider(height: 24),
            Row(
              mainAxisAlignment: MainAxisAlignment.spaceBetween,
              children: [
                 Text(tr('الصافي النهائى'), style: const TextStyle(fontSize: 16, fontWeight: FontWeight.bold, color: AppColors.primary)),
                Text(
                  '${_netAmount.toStringAsFixed(AppConstants.decimalPlaces)} ${AppConstants.currencySymbolEn}',
                  style: const TextStyle(fontSize: 16, fontWeight: FontWeight.bold, color: AppColors.primary),
                ),
              ],
            ),
            const SizedBox(height: 16),
            DropdownButtonFormField<String>(
              value: _paymentMethod,
              decoration:  InputDecoration(
                labelText: tr('طريقة الدفع'),
                isDense: true,
                prefixIcon: const Icon(PhosphorIconsBold.wallet),
              ),
              items:  [
                DropdownMenuItem(value: 'cash', child: Text(tr('نقدي (Cash)'))),
                DropdownMenuItem(value: 'credit', child: Text(tr('آجل (Credit)'))),
              ],
              onChanged: (val) {
                if (val != null) {
                  setState(() {
                    _paymentMethod = val;
                    // Cash = full immediate payment; credit = deferred (0 paid now)
                    if (val == 'cash') {
                      _paidAmountController.text =
                          _netAmount.toStringAsFixed(AppConstants.decimalPlaces);
                    } else {
                      _paidAmountController.text = '0';
                    }
                  });
                }
              },
            ),
            if (_paymentMethod == 'cash') ...[
              const SizedBox(height: 12),
              Consumer(builder: (context, ref, _) {
                final safes = ref.watch(allSafesProvider).value ?? [];
                final cashSafes = safes.whereType<SafeData>()
                    .where((s) => s.safeType == 'cash')
                    .toList();
                if (cashSafes.isEmpty) return const SizedBox.shrink();
                return DropdownButtonFormField<int>(
                  value: _selectedSafeId,
                  decoration:  InputDecoration(
                    labelText: tr('الصندوق'),
                    isDense: true,
                    prefixIcon: const Icon(PhosphorIconsBold.money),
                  ),
                  hint:  Text(tr('افتراضي')),
                  items: cashSafes.map((s) => DropdownMenuItem(
                    value: s.id,
                    child: Text(s.name),
                  )).toList(),
                  onChanged: (val) => setState(() => _selectedSafeId = val),
                );
              }),
            ],
            const SizedBox(height: 16),
            TextFormField(
              controller: _paidAmountController,
              decoration:  InputDecoration(labelText: tr('المبلغ المدفوع'), isDense: true),
              keyboardType: TextInputType.number,
            ),
            const SizedBox(height: 16),
            TextFormField(
              controller: _notesController,
              decoration:  InputDecoration(labelText: tr('ملاحظات'), alignLabelWithHint: true),
              maxLines: 3,
            ),
          ],
        ),
      ),
    );
  }

  Widget _buildSummaryRow(String label, double value) {
    return Padding(
      padding: const EdgeInsets.symmetric(vertical: 4.0),
      child: Row(
        mainAxisAlignment: MainAxisAlignment.spaceBetween,
        children: [
          Text(label, style: const TextStyle(color: AppColors.textMuted)),
          Text('${value.toStringAsFixed(AppConstants.decimalPlaces)} ${AppConstants.currencySymbolEn}'),
        ],
      ),
    );
  }

  Widget _buildActionButtons() {
    return Row(
      mainAxisAlignment: MainAxisAlignment.end,
      children: [
        OutlinedButton(
          onPressed: () => Navigator.pop(context),
          child:  Text(tr('إلغاء')),
        ),
        const SizedBox(width: 8),
        ElevatedButton(
          onPressed: _isLoading ? null : () => _handleSave(isDraft: true),
          style: ElevatedButton.styleFrom(backgroundColor: Colors.grey[700]),
          child:  Text(tr('حفظ كمسودة')),
        ),
        const SizedBox(width: 8),
        // Mirror the sales-invoice flow: dedicated save-and-print button
        // that commits the invoice AND auto-prints A4 in one click.
        if (!widget.isReturn)
          ElevatedButton.icon(
            onPressed: _isLoading
                ? null
                : () => _handleSave(isDraft: false, printAfterSave: true),
            icon: const Icon(PhosphorIconsBold.printer, size: 16),
            label:  Text(tr('حفظ وطباعة')),
            style: ElevatedButton.styleFrom(backgroundColor: AppColors.primary),
          ),
        if (!widget.isReturn) const SizedBox(width: 8),
        ElevatedButton(
          onPressed: _isLoading ? null : () => _handleSave(isDraft: false),
          child: _isLoading
            ? const SizedBox(width: 20, height: 20, child: CircularProgressIndicator(strokeWidth: 2, color: Colors.white))
            : Text(widget.isReturn ? tr('تأكيد المرتجع') : tr('حفظ الفاتورة')),
        ),
      ],
    );
  }

  Future<void> _handleSave({required bool isDraft, bool printAfterSave = false}) async {
    // المخزنُ أوّلاً: الحقلُ الوحيدُ الذي كان غيابُه يمرّ صامتاً. القائمةُ
    // تُنتقى سلفاً متى وُجد مخزنٌ واحدٌ في النطاق، فلا تظهر هذه الرسالةُ إلا
    // حين لا مخزنَ أصلاً — وحينها الرفضُ الصريحُ أوضحُ من فرعٍ خاطئٍ صامت
    // (كان `warehouseId ?? 1` في مُعالِج الحفظ يخترع المخزنَ رقم ١).
    if (_selectedWarehouseId == null) {
      AppToast.show(context, tr('يجب اختيار المخزن قبل حفظ الفاتورة'),
          type: ToastType.error);
      return;
    }

    // Invoice number is optional — the backend generates a short sequential
    // one (PINV-N) when the field is left blank.
    if (_selectedSupplierId == null || _items.isEmpty) {
      AppToast.show(context, tr('يرجى إكمال البيانات الأساسية وإضافة صنف واحد على الأقل'), type: ToastType.error);
      return;
    }

    if (!widget.isReturn && _items.any((line) => line['trackExpiry'] == true &&
        ((line['batchNumber'] as String?)?.trim().isNotEmpty != true ||
            line['expiryDate'] == null))) {
      AppToast.show(context, tr('رقم الدفعة وتاريخ الصلاحية مطلوبان للأصناف المتتبعة للصلاحية'),
          type: ToastType.error);
      return;
    }

    setState(() => _isLoading = true);
    try {
      await widget.onSave(
        partyId: _selectedSupplierId,
        invoiceNumber: _invoiceNumberController.text,
        supplierInvoiceNumber: _supplierInvoiceController.text,
        date: _selectedDate,
        total: _subtotal,
        discount: _discount,
        tax: _taxTotal,
        netAmount: _netAmount,
        // The "المبلغ المدفوع" field is the single source of truth for `paid`
        // in BOTH cash and credit modes. Previously cash mode ignored the
        // field and forced paid=full — so an operator who read the field as
        // "0 → credit" but left the (default) payment method on نقدي got a
        // silent full auto-payment (a supplier voucher they never issued).
        // The نقدي/آجل toggle now only PRESETS this field (full vs 0) via the
        // dropdown onChanged; whatever is shown here is exactly what gets paid.
        // Clamp to [0, net] and accept Arabic-locale input — never negative or
        // over-net.
        paidAmount: (NumberUtils.tryParseLocale(_paidAmountController.text) ?? 0)
            .clamp(0, _netAmount),
        notes: _notesController.text,
        items: _items,
        warehouseId: _selectedWarehouseId,
        costCenterId: _selectedCostCenterId,
        isDraft: isDraft,
        paymentMethod: _paymentMethod,
        safeId: _paymentMethod == 'cash' ? _selectedSafeId : null,
        printAfterSave: printAfterSave,
      );
      if (mounted) Navigator.pop(context);
    } catch (e) {
      if (mounted) AppToast.show(context, tr('خطأ أثناء الحفظ: {e}', {'e': e}), type: ToastType.error);
    } finally {
      if (mounted) setState(() => _isLoading = false);
    }
  }
}
